void sobel(const uint8_t *input, uint8_t *output, int width, int height)
{
    /* Knob Variables Declaration Start */
    float loop_perforation_factor = 1.0;  // Loop Perforation
    int quantize_enabled = 0;            // Quantization
    int shift_bits = 0;                  // Quantization
    int early_exit_threshold = 0;        // Early-Exit Approximation
    int truncate_threshold = 255;        // Truncated Computations
    /* Knob Variables Declaration End */

    // Truncate the number of rows and columns processed based on loop_perforation_factor
    int truncated_height = height * loop_perforation_factor;
    int truncated_width = width * loop_perforation_factor;

    for (int y = 0; y < truncated_height; y++) {
        for (int x = 0; x < truncated_width; x++) {

            // Skip border pixels
            if (x == 0 || x == truncated_width - 1 || y == 0 || y == truncated_height - 1) {
                output[y * width + x] = 0;
                continue;
            }

            // Load 3x3 neighborhood pixels
            int p00 = input[(y - 1) * width + (x - 1)];
            int p01 = input[(y - 1) * width + x];
            int p02 = input[(y - 1) * width + (x + 1)];
            int p10 = input[y * width + (x - 1)];
            int p12 = input[y * width + (x + 1)];
            int p20 = input[(y + 1) * width + (x - 1)];
            int p21 = input[(y + 1) * width + x];
            int p22 = input[(y + 1) * width + (x + 1)];

            // Apply quantization if enabled
            if (quantize_enabled) {
                p00 >>= shift_bits;
                p01 >>= shift_bits;
                p02 >>= shift_bits;
                p10 >>= shift_bits;
                p12 >>= shift_bits;
                p20 >>= shift_bits;
                p21 >>= shift_bits;
                p22 >>= shift_bits;
            }

            // Compute Sobel gradients
            int gx = -p00 + p02 - 2 * p10 + 2 * p12 - p20 + p22;
            int gy = p00 + 2 * p01 + p02 - p20 - 2 * p21 - p22;

            // Early-exit approximation: Skip further computation for low-gradient pixels
            if (early_exit_threshold > 0 && abs(gx) < early_exit_threshold && abs(gy) < early_exit_threshold) {
                output[y * width + x] = 0;
                continue;
            }

            // Compute gradient magnitude
            int mag = abs(gx) + abs(gy);

            // Truncate computation for high-gradient pixels
            if (mag > truncate_threshold) {
                mag = truncate_threshold;
            }

            // Clip gradient magnitude to 255
            if (mag > 255) mag = 255;

            // Write result to output buffer
            output[y * width + x] = (uint8_t)mag;
        }
    }
